export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    const origin = request.headers.get('Origin') || '';
    if (request.method === 'OPTIONS' && url.pathname.startsWith('/api/')) return new Response(null, { status: 204, headers: corsHeaders(origin) });
    if (url.pathname === '/api/razorpay/create-order' && request.method === 'POST') return createOrder(request, env);
    if (url.pathname === '/api/razorpay/verify-payment' && request.method === 'POST') return verifyPayment(request, env);
    if (url.pathname === '/api/orders/save' && request.method === 'POST') return saveOrder(request, env);
    if (url.pathname === '/api/shipping/track' && request.method === 'GET') return trackShipment(request, env);
    if (url.pathname === '/api/reviews' && request.method === 'GET') return listReviews(request, env);
    if (url.pathname === '/api/reviews' && request.method === 'POST') return saveReview(request, env);
    if (url.pathname === '/api/admin/orders' && request.method === 'GET') return listOrders(request, env);
    // Festival Pack story page: clean, indexable product-information URL.
    if (url.pathname === '/festival-pack') {
      const packUrl = new URL(request.url);
      packUrl.pathname = '/festival-pack.html';
      return env.ASSETS.fetch(new Request(packUrl, request));
    }
    // Stage 171: explicitly serve the recipe HTML file for the clean recipe route.
    if (url.pathname === '/track-order') { const u=new URL(request.url); u.pathname='/track-order.html'; return env.ASSETS.fetch(new Request(u, request)); }
    if (url.pathname === '/achari-masala-recipe') {
      const recipeUrl = new URL(request.url);
      recipeUrl.pathname = '/achari-masala-recipe.html';
      return applySeo(await env.ASSETS.fetch(new Request(recipeUrl, request)), false);
    }
    if (url.pathname === '/haldi-bharat-ki-har-rasoi-ki-shaan') {
      const blogUrl = new URL(request.url);
      blogUrl.pathname = '/haldi-bharat-ki-har-rasoi-ki-shaan.html';
      return env.ASSETS.fetch(new Request(blogUrl, request));
    }
    // Jeera blog: keep both clean and .html URLs working when Cloudflare HTML handling is disabled.
    if (url.pathname === '/jeera-khet-se-tadke-tak' || url.pathname === '/jeera-khet-se-tadke-tak.html') {
      const jeeraUrl = new URL(request.url);
      jeeraUrl.pathname = '/jeera-khet-se-tadke-tak.html';
      return env.ASSETS.fetch(new Request(jeeraUrl, request));
    }
    // Black-pepper blog: route both public URL forms through the Worker to the HTML asset.
    // Return the original page as-is so its page-specific metadata is preserved.
    if (url.pathname === '/kali-mirch-kahani' || url.pathname === '/kali-mirch-kahani.html') {
      const blogUrl = new URL(request.url);
      blogUrl.pathname = '/kali-mirch-kahani.html';
      return env.ASSETS.fetch(new Request(blogUrl, request));
    }
    if (url.pathname === '/lal-mirch-ki-kahani' || url.pathname === '/lal-mirch-ki-kahani-v2') {
      const blogUrl = new URL(request.url);
      blogUrl.pathname = '/lal-mirch-ki-kahani.html';
      return env.ASSETS.fetch(new Request(blogUrl, request));
    }
    if (url.pathname === '/garam-masala-recipe') {
      const recipeUrl = new URL(request.url);
      recipeUrl.pathname = '/garam-masala-recipe.html';
      return applySeo(await env.ASSETS.fetch(new Request(recipeUrl, request)), false);
    }
    if (url.pathname === '/assets/festival-15-spice-pack.webp') {
      const source = await env.ASSETS.fetch(new Request(new URL('/assets/festival-15-spice-pack.svg', request.url), request));
      if (source.ok) {
        const svg = await source.text();
        return new Response(svg, {headers:{'Content-Type':'image/svg+xml; charset=UTF-8','Cache-Control':'public, max-age=3600'}});
      }
      return new Response('Festival Pack image unavailable', {status:404});
    }
    // Preview fix: explicitly serve the black-pepper card image through the asset binding.
    // The matching run_worker_first rule in wrangler.jsonc ensures this handler receives the request.
    if (url.pathname === '/assets/02-whole-black-pepper.jpg') {
      const imageUrl = new URL(request.url);
      imageUrl.search = '';
      const imageResponse = await env.ASSETS.fetch(new Request(imageUrl.toString(), { method: request.method, headers: request.headers }));
      if (!imageResponse.ok) return imageResponse;
      const imageHeaders = new Headers(imageResponse.headers);
      imageHeaders.set('Content-Type', 'image/jpeg');
      imageHeaders.set('Cache-Control', 'no-store, max-age=0');
      return new Response(imageResponse.body, { status: imageResponse.status, headers: imageHeaders });
    }

    // Homepage source of truth: the current Stage118 index file.
    // public/index.html is only a placeholder, so / must explicitly serve Stage118.
    let assetRequest = request;
    if (url.pathname === '/' || url.pathname === '/index.html') {
      const homeUrl = new URL(request.url);
      homeUrl.pathname = '/Shudh_Sanjivani_Stage118_index.html';
      // Force a clean GET for the explicit homepage asset.
      assetRequest = new Request(homeUrl.toString(), {
        method: 'GET',
        headers: request.headers
      });
    }
    const assetResponse = await env.ASSETS.fetch(assetRequest);
    // Stage 96: prevent the production HTML from being served from an older edge/browser cache.
    // This is important while deploying the checkout/order-flow fix.
    const headers = new Headers(assetResponse.headers);
    if (url.pathname === '/' || url.pathname === '/index.html') {
      headers.set('Cache-Control', 'no-store, no-cache, must-revalidate, max-age=0');
      headers.set('Pragma', 'no-cache');
      headers.set('Expires', '0');
    }
    const response = new Response(assetResponse.body, { status: assetResponse.status, statusText: assetResponse.statusText, headers });
    // Preview safety: serve the homepage HTML directly. This keeps the restored homepage
    // independent of HTMLRewriter while we verify the original images/layout.
    if (url.pathname === '/' || url.pathname === '/index.html') return applySeo(response, true);
    return applySeo(response, false);
  }
};
